const items = $input.all();
const payload = items[0].json.body;
const action = payload.action;
const pr = payload.pull_request || {};
if (action !== 'opened' && action !== 'synchronize') {
  return [];
}
const owner = pr.base?.repo?.owner?.login || '';
const repo = pr.base?.repo?.name || '';
const prNumber = pr.number || 0;
const diffUrl = pr.diff_url || `https://api.github.com/repos/${owner}/${repo}/pulls/${prNumber}`;
return [{
  json: {
    owner,
    repo,
    prNumber,
    prTitle: pr.title || '',
    prBody: pr.body || '',
    diffUrl,
    commentsUrl: pr.comments_url || `https://api.github.com/repos/${owner}/${repo}/issues/${prNumber}/comments`
  }
}];

const items = $input.all();
const diff = (items[0].json.data || items[0].json.body || '').toString();
// Truncate diff if too long
const maxLen = 12000;
const truncatedDiff = diff.length > maxLen ? diff.substring(0, maxLen) + '\n... [truncated]' : diff;
return [{ json: { ...items[0].json, diff: truncatedDiff } }];
